import { readFile, realpath, stat } from "node:fs/promises";
import { isAbsolute, relative, resolve, sep } from "node:path";
import { tmpdir } from "node:os";
import { z } from "zod";

const outputDetails = z.object({ fullOutputPath: z.string() });
const key = (path: string) => process.platform === "win32" ? path.toLowerCase() : path;

/** Exact, read-only capabilities for files generated by SDK tool output truncation. */
export class ToolOutputFiles {
  private readonly files = new Map<string, { path: string; dev: number; ino: number; size: number; mtimeMs: number }>();

  async capture(tool: string, details: unknown): Promise<void> {
    if (tool !== "Bash" && !tool.startsWith("mcp__")) return;
    const result = outputDetails.safeParse(details);
    if (!result.success || !isAbsolute(result.data.fullOutputPath)) return;
    const path = await realpath(result.data.fullOutputPath);
    const rel = relative(await realpath(tmpdir()), path);
    if (rel === ".." || rel.startsWith(`..${sep}`) || isAbsolute(rel)) return;
    const info = await stat(path);
    if (info.isFile()) this.files.set(key(resolve(result.data.fullOutputPath)), { path, dev: info.dev, ino: info.ino, size: info.size, mtimeMs: info.mtimeMs });
  }

  async resolve(cwd: string, path: string): Promise<string | undefined> {
    const record = this.files.get(key(resolve(cwd, path)));
    if (!record) return undefined;
    const actual = await realpath(resolve(cwd, path));
    const info = await stat(actual);
    if (key(actual) !== key(record.path) || info.dev !== record.dev || info.ino !== record.ino
      || info.size !== record.size || info.mtimeMs !== record.mtimeMs || !info.isFile()) {
      throw new Error("Saved tool output changed. Run the producing tool again before reading it.");
    }
    return actual;
  }

  async read(cwd: string, path: string): Promise<Buffer | undefined> {
    const actual = await this.resolve(cwd, path);
    if (!actual) return undefined;
    if ((await stat(actual)).size > 64 * 1024 * 1024) throw new Error("Tool output exceeds the 64 MiB read limit. Use CodeMode to filter the result before returning it.");
    return readFile(actual);
  }
}
